import glob
import unittest

# Load the RobotPet class from the exercise file printed in the book.
for path in sorted(glob.glob("*.py")):
    source = open(path).read()
    if "class RobotPet" in source and "unittest" not in source:
        exec(compile(source, path, "exec"))
        break


class TestRobotPet(unittest.TestCase):
    def test_name_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.name, "Bolt")

    def test_battery_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.battery, 100)

    def test_mood_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.mood, "happy")

    def test_show_talent(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.show_talent(), "performs a generic trick!")


if __name__ == "__main__":
    unittest.main(verbosity=2)

import unittest

from robot_pet import RobotPet


def make_pet():
    """Create a RobotPet, whatever arguments its constructor happens to take."""
    for args in (("Robo", "Dog"), ("Robo",), (), ("Robo", "Dog", 100)):
        try:
            return RobotPet(*args)
        except TypeError:
            continue
    return RobotPet.__new__(RobotPet)


with open("unit_tests_that_change_state.py") as source_file:
    printed_tests = source_file.read()

class_source = (
    "class TestRobotPet(unittest.TestCase):\n"
    "    def setUp(self):\n"
    "        self.pet = make_pet()\n\n" + printed_tests
)

namespace = {"unittest": unittest, "make_pet": make_pet}
exec(class_source, namespace)
TestRobotPet = namespace["TestRobotPet"]

if __name__ == "__main__":
    unittest.main(argv=["run_tests.py"], verbosity=2)

class RobotPet:
    def __init__(self, name, battery=100, mood="neutral"):
        self.name = name
        self.battery = battery
        self.mood = mood

    def speak(self):
        if self.battery < 30:
            return f"{self.name} mumbles: I need a recharge."
        if self.mood == "happy":
            return f"{self.name} says: I am so happy to see you!"
        return f"Hello, I am {self.name}."


class RobotCat(RobotPet):
    def speak(self):
        if self.battery < 30:
            return f"{self.name} is too tired to purr."
        if self.mood == "happy":
            return f"{self.name} is one happy kitty!"
        return f"Meow! I am {self.name}."


class RobotBird(RobotPet):
    def speak(self):
        if self.battery < 30:
            return f"{self.name} peeps: my battery is low."
        if self.mood == "happy":
            return f"{self.name} sings a lovely song!"
        return f"Chirp! I am {self.name}."


class RobotDog(RobotPet):
    def speak(self):
        if self.battery < 30:
            return f"{self.name} whines: I need to charge."
        if self.mood == "happy":
            return f"Best day ever, barks {self.name}!"
        return f"Woof! I am {self.name}."


if __name__ == "__main__":
    pets = [RobotPet("Robo"), RobotCat("Whiskers"),
            RobotBird("Tweety"), RobotDog("Rex")]
    for pet in pets:
        pet.battery = 50
        pet.mood = "neutral"
        print(pet.speak())
        pet.mood = "happy"
        print(pet.speak())
        pet.battery = 10
        print(pet.speak())
